"use client";

import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";
import { createContext, type ReactNode, useContext, useId } from "react";
import { cn } from "../lib/cn.js";
import { motion, spring, useReducedMotion } from "../motion/index.js";
import { touchTarget } from "./touch.js";

// Generated by shadcn (Base UI, Mira) and rewritten: a segmented control on a `well` track with
// `--radius-pill`. The selected tab is a `sheet` chip with `ink` 600 text, and the chip travels
// between tabs as a layout morph on the `page` spring (transform only, M9). Under reduced motion it
// moves instantly (M10).

const TabsGroup = createContext<string>("tabs");

export function Tabs({ className, ...props }: TabsPrimitive.Root.Props) {
  const id = useId();
  return (
    <TabsGroup.Provider value={id}>
      <TabsPrimitive.Root
        data-slot="tabs"
        className={cn("flex flex-col gap-4", typeof className === "string" ? className : undefined)}
        {...props}
      />
    </TabsGroup.Provider>
  );
}

// The track scrolls in a square wrapper, not on the pill itself: overflow on a rounded box clips to
// its curve, which would cut the focus ring at the pill's ends. Scrolling on x makes overflow-y
// auto too, so on a coarse pointer the wrapper pads 2px top and bottom (with a matching negative
// margin, so layout doesn't move): a 32px tab's 44px hit area reaches 6px past it, 4px of which
// is the pill's own padding. Without this the wrapper clips the hit area to 40px and scrolls 2px.
export function TabsList({ className, ...props }: TabsPrimitive.List.Props) {
  return (
    <div
      data-slot="tabs-scroll"
      className="max-w-full overflow-x-auto pointer-coarse:-my-0.5 pointer-coarse:py-0.5"
    >
      <TabsPrimitive.List
        data-slot="tabs-list"
        className={cn(
          "inline-flex w-fit items-center gap-0.5 rounded-pill bg-well p-1",
          typeof className === "string" ? className : undefined,
        )}
        {...props}
      />
    </div>
  );
}

function ActiveChip() {
  const reduced = useReducedMotion();
  const group = useContext(TabsGroup);
  return (
    <motion.span
      layoutId={`${group}-chip`}
      transition={reduced ? { duration: 0 } : spring.page}
      aria-hidden="true"
      className="absolute inset-0 -z-10 rounded-pill bg-sheet inset-ring-1 inset-ring-rule"
    />
  );
}

export function TabsTrigger({
  className,
  children,
  ...props
}: Omit<TabsPrimitive.Tab.Props, "children"> & { children?: ReactNode }) {
  return (
    <TabsPrimitive.Tab
      data-slot="tabs-trigger"
      className={cn(
        "relative isolate inline-flex h-8 shrink-0 items-center justify-center gap-1.5 rounded-pill px-4",
        "font-sans text-sm font-medium whitespace-nowrap text-ink-soft",
        "transition-colors duration-(--dur-quick) ease-out hover:text-ink",
        "data-active:font-semibold data-active:text-ink",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink",
        "data-disabled:text-ink-faint data-disabled:pointer-events-none",
        "[&_svg]:size-4 [&_svg]:shrink-0",
        touchTarget,
        typeof className === "string" ? className : undefined,
      )}
      render={(renderProps, state) => (
        <button type="button" {...renderProps}>
          {state.active ? <ActiveChip /> : null}
          {/* The label sits over an invisible 600-weight copy, so every tab is always as wide as
              its selected self: siblings never reflow and the chip's target never moves. */}
          <span className="inline-grid">
            <span
              data-slot="tabs-label-reserve"
              aria-hidden="true"
              className="invisible col-start-1 row-start-1 inline-flex items-center gap-1.5 font-semibold"
            >
              {children}
            </span>
            <span className="col-start-1 row-start-1 inline-flex items-center justify-center gap-1.5">
              {children}
            </span>
          </span>
        </button>
      )}
      {...props}
    />
  );
}

export function TabsContent({ className, ...props }: TabsPrimitive.Panel.Props) {
  return (
    <TabsPrimitive.Panel
      data-slot="tabs-content"
      className={cn(
        "rounded-field outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink",
        typeof className === "string" ? className : undefined,
      )}
      {...props}
    />
  );
}
